// Implements: design/narrative/kich_ban_chuan.md section 4 ("Bang 1", 10 waves), design/game-brief.md MVP 2,
// production/epics/micro-arena-survivor/story-003-arena-waves.md.
//
// Every wave count, timer, trap value and arena size lives here. Values marked [PLACEHOLDER] are not specified
// by the design and are expected to be rebalanced after playtests. The asset generated by ArenaSceneBuilder
// holds the Bang 1 values; the field defaults below are only the fallback for a fresh asset.

using System;
using MicroArena.Gameplay.Bosses;
using MicroArena.Gameplay.Enemies;
using UnityEngine;

namespace MicroArena.Gameplay.Config
{
    /// <summary>How a wave is won.</summary>
    public enum WaveGoal
    {
        /// <summary>Kill <c>KillTarget</c> enemies. Exactly that many are spawned.</summary>
        Kill,
        /// <summary>Survive <c>SurviveSeconds</c> or kill <c>KillTarget</c>, whichever comes first. Spawns never stop.</summary>
        SurviveOrKill,
        /// <summary>Kill the boss, and no escort (<c>EscortCount</c> extra enemies spawned from the pool) may remain alive.</summary>
        Boss,
    }

    /// <summary>One weighted entry of a wave's spawn pool.</summary>
    [Serializable]
    public sealed class WaveSpawnEntry
    {
        [Tooltip("Enemy prefab to instantiate.")]
        [SerializeField] private EnemyBase _prefab;
        [Tooltip("Config injected into the spawned enemy.")]
        [SerializeField] private EnemyConfig _config;
        [Tooltip("Relative chance of this entry being picked.")]
        [SerializeField, Min(0)] private int _weight = 1;

        /// <summary>Enemy prefab to instantiate.</summary>
        public EnemyBase Prefab => _prefab;
        /// <summary>Config injected into the spawned enemy.</summary>
        public EnemyConfig Config => _config;
        /// <summary>Relative pick chance.</summary>
        public int Weight => _weight;
    }

    /// <summary>Data of one wave.</summary>
    [Serializable]
    public sealed class WaveDefinition
    {
        [SerializeField] private WaveGoal _goal = WaveGoal.Kill;
        [Tooltip("Kills needed (Kill, SurviveOrKill).")]
        [SerializeField, Min(1)] private int _killTarget = 15;
        [Tooltip("Seconds to survive (SurviveOrKill only).")]
        [SerializeField, Min(0f)] private float _surviveSeconds = 60f;
        [Tooltip("Enemies spawned over time during the wave.")]
        [SerializeField] private WaveSpawnEntry[] _spawnPool = Array.Empty<WaveSpawnEntry>();
        [Tooltip("Boss prefab spawned at wave start (Boss only): Gargoyle Tyrant or Void Warden.")]
        [SerializeField] private BossBase _bossPrefab;
        [Tooltip("Boss tuning injected into the boss (Boss only).")]
        [SerializeField] private BossConfig _bossConfig;
        // [PLACEHOLDER] Kind of the 4 Wave 5 support enemies is not specified (Crawlers for now).
        [Tooltip("Extra enemies spawned from the pool during a Boss wave.")]
        [SerializeField, Min(0)] private int _escortCount;

        /// <summary>How the wave is won.</summary>
        public WaveGoal Goal => _goal;
        /// <summary>Kills needed (Kill, SurviveOrKill).</summary>
        public int KillTarget => _killTarget;
        /// <summary>Seconds to survive (SurviveOrKill).</summary>
        public float SurviveSeconds => _surviveSeconds;
        /// <summary>Weighted pool for spawns over time.</summary>
        public WaveSpawnEntry[] SpawnPool => _spawnPool;
        /// <summary>Boss prefab (Boss).</summary>
        public BossBase BossPrefab => _bossPrefab;
        /// <summary>Boss config (Boss).</summary>
        public BossConfig BossConfig => _bossConfig;
        /// <summary>Pool spawns of a Boss wave.</summary>
        public int EscortCount => _escortCount;

        /// <summary>How many pool spawns the wave allows; -1 means unlimited.</summary>
        public int PoolSpawnLimit => _goal switch
        {
            WaveGoal.Kill => _killTarget,
            WaveGoal.Boss => _escortCount,
            _ => -1,
        };
    }

    /// <summary>
    /// The 10-wave run, the spawner limits, the arena size and the rotating trap. One asset per game.
    /// </summary>
    [CreateAssetMenu(fileName = "WaveConfig", menuName = "Micro Arena Survivor/Wave Config")]
    public sealed class WaveConfig : ScriptableObject
    {
        [Header("Waves (Bang 1)")]
        [SerializeField] private WaveDefinition[] _waves = Array.Empty<WaveDefinition>();

        [Header("Spawning")]
        // [PLACEHOLDER] Spawn rhythm is not specified.
        [Tooltip("[PLACEHOLDER] Seconds between two spawns while below the alive limit.")]
        [SerializeField, Min(0.01f)] private float _spawnInterval = 0.8f;
        // [PLACEHOLDER] Max enemies alive at once is not specified.
        [Tooltip("[PLACEHOLDER] Maximum enemies alive at the same time.")]
        [SerializeField, Min(1)] private int _maxAlive = 12;
        // [PLACEHOLDER] Spawn positions are not specified: random points along the walls.
        [Tooltip("[PLACEHOLDER] Spawn points lie on a square this many metres inside the walls.")]
        [SerializeField, Min(0f)] private float _spawnInset = 2f;
        [Tooltip("[PLACEHOLDER] A spawn point closer than this to Kaelen is mirrored to the opposite side.")]
        [SerializeField, Min(0f)] private float _minSpawnDistanceFromPlayer = 8f;

        [Header("Arena")]
        // [PLACEHOLDER] Arena size is not specified (40 m like the story-001 sandbox).
        [Tooltip("[PLACEHOLDER] Side of the square floor in metres.")]
        [SerializeField, Min(5f)] private float _arenaSize = 40f;
        [Tooltip("[PLACEHOLDER] Wall height in metres.")]
        [SerializeField, Min(0.1f)] private float _wallHeight = 2f;
        [Tooltip("[PLACEHOLDER] Wall thickness in metres.")]
        [SerializeField, Min(0.1f)] private float _wallThickness = 1f;
        [Tooltip("[PLACEHOLDER] Kaelen and enemies are kept this many metres off the wall faces.")]
        [SerializeField, Min(0f)] private float _boundsPadding = 0.5f;

        [Header("Run flow")]
        [Tooltip("Seconds between the final death and the restart at Wave 1 (when auto-restart is on).")]
        [SerializeField, Min(0f)] private float _defeatRestartDelay = 2f;

        [Header("Rotating trap")]
        [Tooltip("First wave (1-based) in which the trap is active.")]
        [SerializeField, Min(1)] private int _trapStartWave = 8;
        [Tooltip("Seconds per full revolution.")]
        [SerializeField, Min(0.1f)] private float _trapSecondsPerRevolution = 6f;
        [Tooltip("Damage per contact.")]
        [SerializeField, Min(0f)] private float _trapDamage = 15f;
        // [PLACEHOLDER] Re-hit delay is not specified; without it the trap would hit every frame.
        [Tooltip("[PLACEHOLDER] Seconds after a landed hit before the trap can hit Kaelen again.")]
        [SerializeField, Min(0f)] private float _trapContactCooldown = 0.75f;
        // [PLACEHOLDER] Blade size is not specified.
        [Tooltip("[PLACEHOLDER] Full length (m) of the blade bar, centred on the arena middle.")]
        [SerializeField, Min(0.1f)] private float _trapLength = 12f;
        [Tooltip("[PLACEHOLDER] Width (m) of the blade bar.")]
        [SerializeField, Min(0.05f)] private float _trapWidth = 0.6f;
        [Tooltip("[PLACEHOLDER] Height (m) of the blade bar (visual only).")]
        [SerializeField, Min(0.05f)] private float _trapHeight = 0.5f;
        [Tooltip("[PLACEHOLDER] Kaelen's body radius (m) added to the blade bounds for the contact test.")]
        [SerializeField, Min(0f)] private float _trapHitPadding = 0.5f;

        /// <summary>Number of waves in a run.</summary>
        public int WaveCount => _waves.Length;
        /// <summary>Wave by 1-based number.</summary>
        public WaveDefinition GetWave(int waveNumber) => _waves[waveNumber - 1];

        /// <summary>Seconds between spawns.</summary>
        public float SpawnInterval => _spawnInterval;
        /// <summary>Max enemies alive at once.</summary>
        public int MaxAlive => _maxAlive;
        /// <summary>Distance of spawn points inside the walls.</summary>
        public float SpawnInset => _spawnInset;
        /// <summary>Minimum distance of a spawn point to Kaelen.</summary>
        public float MinSpawnDistanceFromPlayer => _minSpawnDistanceFromPlayer;

        /// <summary>Side of the square floor in metres.</summary>
        public float ArenaSize => _arenaSize;
        /// <summary>Wall height.</summary>
        public float WallHeight => _wallHeight;
        /// <summary>Wall thickness.</summary>
        public float WallThickness => _wallThickness;
        /// <summary>Largest |x| or |z| a body may reach (half the arena minus half a wall minus padding).</summary>
        public float PlayableHalfExtent => _arenaSize * 0.5f - _wallThickness * 0.5f - _boundsPadding;

        /// <summary>Seconds from the final death to the restart.</summary>
        public float DefeatRestartDelay => _defeatRestartDelay;

        /// <summary>First wave with the trap active (1-based).</summary>
        public int TrapStartWave => _trapStartWave;
        /// <summary>Seconds per revolution.</summary>
        public float TrapSecondsPerRevolution => _trapSecondsPerRevolution;
        /// <summary>Damage per contact.</summary>
        public float TrapDamage => _trapDamage;
        /// <summary>Re-hit delay after a landed hit.</summary>
        public float TrapContactCooldown => _trapContactCooldown;
        /// <summary>Blade bar full length.</summary>
        public float TrapLength => _trapLength;
        /// <summary>Blade bar width.</summary>
        public float TrapWidth => _trapWidth;
        /// <summary>Blade bar height.</summary>
        public float TrapHeight => _trapHeight;
        /// <summary>Kaelen radius added to the blade bounds.</summary>
        public float TrapHitPadding => _trapHitPadding;
    }
}
